  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let ID: VOffset = 4
    static let CONSTELLATION: VOffset = 6
    static let OPERATOR: VOffset = 8
    static let ASN: VOffset = 10
    static let AS_NAME: VOffset = 12
    static let SERVICE_TIER: VOffset = 14
    static let REGION: VOffset = 16
    static let WINDOW_START: VOffset = 18
    static let WINDOW_STOP: VOffset = 20
    static let AGGREGATION_PERIOD: VOffset = 22
    static let METRICS: VOffset = 24
    static let SOURCES: VOffset = 26
    static let CREATED_AT: VOffset = 28
    static let UPDATED_AT: VOffset = 30
    static let SUPERSEDES_CNP_CID: VOffset = 32
  }

