  public static func add(OPERATOR: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OPERATOR, at: VT.OPERATOR) }
  public static func add(ASN: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ASN, def: 0, at: VT.ASN) }
  public static func add(AS_NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: AS_NAME, at: VT.AS_NAME) }
  public static func add(SERVICE_TIER: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SERVICE_TIER, at: VT.SERVICE_TIER) }
  public static func add(REGION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REGION, at: VT.REGION) }
  public static func add(WINDOW_START: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: WINDOW_START, at: VT.WINDOW_START) }
  public static func add(WINDOW_STOP: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: WINDOW_STOP, at: VT.WINDOW_STOP) }
  public static func add(AGGREGATION_PERIOD: cnpPeriod, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AGGREGATION_PERIOD.rawValue, def: 0, at: VT.AGGREGATION_PERIOD) }
  public static func addVectorOf(METRICS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: METRICS, at: VT.METRICS) }
  public static func addVectorOf(SOURCES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCES, at: VT.SOURCES) }
  public static func add(CREATED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CREATED_AT, at: VT.CREATED_AT) }
  public static func add(UPDATED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: UPDATED_AT, at: VT.UPDATED_AT) }
  public static func add(SUPERSEDES_CNP_CID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SUPERSEDES_CNP_CID, at: VT.SUPERSEDES_CNP_CID) }
  public static func endCNP(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createCNP(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset = Offset(),
    CONSTELLATIONOffset CONSTELLATION: Offset = Offset(),
    OPERATOROffset OPERATOR: Offset = Offset(),
    ASN: UInt32 = 0,
    AS_NAMEOffset AS_NAME: Offset = Offset(),
    SERVICE_TIEROffset SERVICE_TIER: Offset = Offset(),
    REGIONOffset REGION: Offset = Offset(),
    WINDOW_STARTOffset WINDOW_START: Offset = Offset(),
    WINDOW_STOPOffset WINDOW_STOP: Offset = Offset(),
    AGGREGATION_PERIOD: cnpPeriod = .custom,
    METRICSVectorOffset METRICS: Offset = Offset(),
    SOURCESVectorOffset SOURCES: Offset = Offset(),
    CREATED_ATOffset CREATED_AT: Offset = Offset(),
    UPDATED_ATOffset UPDATED_AT: Offset = Offset(),
    SUPERSEDES_CNP_CIDOffset SUPERSEDES_CNP_CID: Offset = Offset()
  ) -> Offset {
    let __start = CNP.startCNP(&fbb)
    CNP.add(ID: ID, &fbb)
    CNP.add(CONSTELLATION: CONSTELLATION, &fbb)
